import { AppState } from "./state.js";

export function getSkillById(skillId) {
  for (const skill of Object.values(AppState.skills)) {
    const content = skill.Content;
    if (content.hasOwnProperty(skillId)) {
      return content[skillId];
    }
  }
  return null;
}

export function getWeaponByHeroId(heroId) {
  const table = AppState.weapons.HeroSpWeapon.Content
  for (const weapon of Object.values(table)) {
    if (weapon.HeroId == heroId) {
      return weapon;
    }
  }
  return null;
}

/**
 * 【保留函數 1】取得所有角色編號與其技能清單
 * 回傳： [{ heroId, name, iconUrl, weaponId, skillIds: [...] }, ...]
 * 目前實作：從 AppState.skills 依 heroId 分組。改資料結構的話改這裡就好。
 */
export function getAllHeroesAndSkills() {
  let result = [];
  for (const heroId in AppState.heroes) {
    const hero = AppState.heroes[heroId];
    if (hero.Name == 50105740) continue;  // 過濾掉「無角色」的假資料

    const name = AppState.strings[hero.Name] || hero.Name;
    const skillIds = hero.Skill;
    const weapon = getWeaponByHeroId(heroId);
    result.push({
      heroId: heroId,
      name: name,
      iconUrl: "assets\\hero\\normal\\" + heroId + ".png",
      weaponId: weapon ? weapon.AttriSp : null,
      skillIds: skillIds,
    });
  }

  return result;
}

function getKeyList(key) {
  if (key.includes("_")) {
    return key.split("_");
  } else {
    return [key];
  }
}

function equalMap(tbl1, tbl2) {
  // 1. 記憶體位址相同，直接傳回 true
  if (tbl1 === tbl2) {
    return true;
  }

  // 2. 其中一個為 null/undefined，或型別不是物件，直接傳回 false
  if (!tbl1 || !tbl2 || typeof tbl1 !== 'object' || typeof tbl2 !== 'object') {
    return false;
  }

  const keys1 = Object.keys(tbl1);
  const keys2 = Object.keys(tbl2);

  // 3. 比較 Key 的數量 (對應 Lua 的 table.size)
  if (keys1.length !== keys2.length) {
    return false;
  }

  // 4. 逐一檢查 Key 與對應的 Value 是否相等
  for (const key of keys1) {
    if (tbl2[key] !== tbl1[key]) {
      return false;
    }
  }

  return true;
}

function getStarTotalAdd(skillType, tKey, tIndex, star) {
  if (star < 1) {
    return 0;
  }
  let starAdd = 0;
  for (let i = 1; i <= star; i++) {
    starAdd += getStarAdd(skillType, tKey, tIndex, i);
  }
  return starAdd;
}

function getStarAdd(skillType, tKey, tIndex, star) {
  const skillInfo = getSkillById(skillType) || {};
  const dataShow = skillInfo.DataShow || [];
  const starEff = skillInfo.starEff || {};
  const actEff = skillInfo.actEff2;
  let add = 0;

  if (!skillInfo.starShow) {
    return add;
  }

  // if (skillType == 2157 && star == 1) {
  //   console.log("DEBUG")
  // }

  // Lua ipairs is 1-indexed; JS arrays are 0-indexed.
  // imlType is converted to 1-based index to maintain key/logic alignment.
  for (let i = 0; i < dataShow.length; i++) {
    const imlType = i + 1;
    const datas = dataShow[i];

    if (imlType === tIndex) {
      let effTbl = starEff[imlType - 1];

      if (imlType > 1 && actEff && actEff[imlType - 2]) {
        effTbl = actEff[imlType - 2].starEff;
      }

      for (const dataPair of datas || []) {
        let key = null;
        let valueType = null;
        let extSkillType = skillType;

        for (const [k, v] of Object.entries(dataPair || {})) {
          if (k === "skillType") {
            extSkillType = v;
          } else {
            key = k;
            valueType = v;
          }
        }

        let extEffTbl = null;
        for (const tbl of effTbl || []) {
          const oriKeyList = tbl[0];
          const oriValueTbl = tbl[1];

          if (equalMap(oriKeyList, getKeyList(key))) {
            extEffTbl = oriValueTbl;
          }
        }

        if (extEffTbl && key === tKey) {
          const funcType = Math.floor(valueType / 10);
          const numType = valueType % 10;
          // Handles both 1-indexed Lua arrays or Object maps for star values
          const value = extEffTbl[star - 1] ?? 0;

          if (value > 0) {
            add = value;
          }
        }
      }
    }
  }

  return add;
}

function getValueTbl(valueTbl, key) {
  // 如果 Key 包含底線，進行拆解走訪
  if (key.includes("_")) {
    const keyList = key.split("_");
    let tbl = valueTbl;
    const keyCnt = keyList.length;

    for (let idx = 0; idx < keyCnt; idx++) {
      let oriKey = keyList[idx];

      // 嘗試轉為數字（等價於 Lua 的 tonumber）
      const convertKey = Number(oriKey);
      if (!isNaN(convertKey) && oriKey.trim() !== "") {
        oriKey = convertKey;
      }

      // 若非最後一個 key，且目前層級存在，則向下尋找
      if (tbl && tbl[oriKey] !== undefined && idx !== keyCnt - 1) {
        tbl = tbl[oriKey];
      }

      key = oriKey;
    }

    return [tbl, key]; // JS 回傳陣列以支援解構接收
  }

  return [valueTbl, key];
}

const SKILL_VALUE_FUNC = {
  [1]: function (valueTbl, key, lv, skillType) {
    return valueTbl[key]
  },
  [2]: function (valueTbl, key, lv, skillType) {
    if (valueTbl == null) {
      console.log("123")
    }
    return valueTbl[key][lv - 1]
  },
}

function formatDecimal(num, precision = 2) {
  return new Intl.NumberFormat('en-US', {
    maximumFractionDigits: precision
  }).format(num);
}
function getSkillArgs(skillType, lv, nextLv, star) {
  const skill = getSkillById(skillType)
  const dataShow = skill.DataShow;
  const isOverSea = !AppState.isOverSea;  // 是否海外版（目前沒用到，保留給你自己判斷）
  const norEff = isOverSea ? skill.norEff2 : skill.norEff;
  const actEff = isOverSea ? skill.actEff2 : skill.actEff;
  let args = [];

  for (let imlType = 1; imlType <= dataShow.length; imlType++) {
    const datas = dataShow[imlType - 1]; // Lua 1-based index 轉為 JS 0-based index
    let effTbl = norEff[imlType - 1];

    if (1 < imlType && actEff && actEff[imlType - 2]) {
      effTbl = actEff[imlType - 2].parmTbl;
    }

    for (const dataPair of datas) {
      let key, valueType;
      let extSkillType = skillType;

      for (const [k, v] of Object.entries(dataPair)) {
        if (k === "skillType") {
          extSkillType = v;
        } else {
          key = k;
          valueType = v;
        }
      }

      let extEffTbl = effTbl;
      if (extSkillType !== skillType) {
        const extNorEff = getSkillById(extSkillType, isOverSea).norEff;
        if (actEff) {
          extEffTbl = extNorEff[imlType - actEff.length - 1];
        } else {
          extEffTbl = extNorEff[imlType - 1];
        }
      }

      let funcType = Math.floor(valueType / 10);
      let color = "#42ff81";

      if (2 < funcType) {
        color = "#ff5858";
        funcType = funcType - 2;
      }

      const numType = valueType % 10;
      const [valueTbl, valueKey] = getValueTbl(extEffTbl, key);

      // 注意：JS 中的 SKILL_VALUE_FUNC 索引通常為 0-based，若您的函式陣列是用 1-based，請調整為 funcType - 1
      let value = SKILL_VALUE_FUNC[funcType](valueTbl, valueKey, lv, extSkillType);
      let starAdd = 0;

      if (isOverSea && star && 0 < star) {
        starAdd = getStarTotalAdd(skillType, key, imlType, star);
        value = value + starAdd;
      }
      if (numType === 0) {
        value = `${formatDecimal(value * 100)}%`;
      } else if (numType === 2) {
        value = `${formatDecimal(value * 100)}`;
      }

      args.push(`[color=${color}]${value}[/color]`);

    }
  }

  return args;
}

function format(template, args) {
  // 將傳入的參數打平（支援傳入 array 或多個單獨參數）
  const params = args.flat();
  let index = 0;

  if (template === undefined) {
    return "NULL"
  }

  return template.replace(/%s/g, (match) => {
    // 若參數數量不足，可選擇保留 %s 或替換成空字串/預設值
    if (index < params.length) {
      const val = params[index++];
      return val !== undefined && val !== null ? String(val) : '';
    }
    return match; // 參數不夠時保留原本的 %s
  });
}

/**
 * 【保留函數 2】依照目前星級設定，計算並回傳格式化後的技能描述
 *
 * @param {string} heroId   角色編號
 * @param {string} skillId  技能編號
 * @param {object} effective  這個技能最終生效的數值：
 *        {
 *          charStar:   number,  // 英雄星級（全域共用）
 *          skillStar:  number,  // 此技能的星級（可能來自全域「技能等級」，也可能被單獨調整過）
 *        }
 * @returns {string} 已算好數值、顏色標籤也轉成 <span> 的 HTML 字串
 *
 * 範例邏輯：
 *   1. 用 skillStar 查 valuesByStar 對應星級的數值（超出範圍取最接近星級）
 *   2. 套用 template 佔位符
 *   3. 呼叫 parseColorTags() 轉換顏色標籤
 * 實際換算公式、要不要讓 charStar 也影響數值，都在這裡自行調整即可。
 */
export function formatSkillDescription(skillId, effective) {
  const skill = getSkillById(skillId);
  if (!skill) return "（找不到此技能資料）";

  const desc = AppState.strings[skill.SkillDes] || skill.template;
  const skillStar = effective.skillStar;
  const heroStar = effective.charStar;
  const args = getSkillArgs(skillId, skillStar, false, heroStar)
  const text = format(desc, args)
  return parseColorTags(text);
}

/**
 * 【保留函數 4】依照目前專武等級，計算並回傳格式化後的專武描述
 * （專武現在併入技能清單一起處理，用同一套 +/- 邏輯獨立調整）
 *
 * @param {string} weaponId     專武編號
 * @param {object} effective  這個技能最終生效的數值：
 *        {
 *          charStar:   number,  // 英雄星級（全域共用）
 *          skillStar:  number,  // 此技能的星級（可能來自全域「技能等級」，也可能被單獨調整過）
 *        }
 * @returns {string} 已算好數值、顏色標籤也轉成 <span> 的 HTML 字串
 *
 * 範例邏輯：用 weaponLevel 查 valuesByStar 對應等級的數值，組出描述文字。
 * 實際欄位與公式請依你的專武資料結構自行調整。
 */
export function formatWeaponDescription(weaponId, effective) {
  const skill = getSkillById(weaponId, effective);
  if (!skill) return "（找不到此專武資料）";

  const text = AppState.strings[skill.SkillDes] || skill.template;
  return parseColorTags(text);
}

/** 輔助函數：在可選星級清單中找最接近目前值的星級（不用改） */
export function clampToNearest(value, sortedOptions) {
  if (sortedOptions.length === 0) return value;
  let closest = sortedOptions[0];
  for (const opt of sortedOptions) {
    if (Math.abs(opt - value) < Math.abs(closest - value)) closest = opt;
  }
  return closest;
}

/**
 * 【保留函數 3】把 BBCode 風格標籤轉成原生 HTML
 *   [color=#hex]文字[/color]  -> <span style="color:#hex">文字</span>（支援巢狀）
 *   [url={...}]文字[/url]     -> 文字（移除標籤，保留內層文字）
 * 這是原本 Python 腳本 clean_bbcode() 的 JS 版本，邏輯完全對應。
 * 之後若遇到新的標籤格式，也是在這裡加規則即可。
 */
export function parseColorTags(text) {
  if (!text) return "";

  // 移除 [url={...}]...[/url]，保留內層文字，重複處理以支援巢狀
  let prev = null;
  while (prev !== text) {
    prev = text;
    text = text.replace(/\[url=\{[^}]*\}\](.*?)\[\/url\]/gs, "$1");
  }
  
  prev = null;
  while (prev !== text) {
    prev = text;
    text = text.replace(/\[img\](.*?)\[\/img\]/gs, "");
  }

  // [color=#hex]...[/color] -> <span style="color:#hex">...</span>，由內而外反覆替換
  prev = null;
  while (prev !== text) {
    prev = text;
    text = text.replace(
      /\[color=(#[0-9a-fA-F]{3,6})\]((?:(?!\[color=)(?!\[\/color\]).)*?)\[\/color\]/gs,
      '<span style="color:$1">$2</span>'
    );
  }
  return text.trim();
}
