/* =========================================================================
 * render.js —— 畫面渲染：角色列表 / 展開內容 / 圖示 / 星星按鈕 / stepper
 * ========================================================================= */

import {
  AppState, SKILL_STAR_MIN, SKILL_STAR_MAX,
  WEAPON_LEVEL_MIN, WEAPON_LEVEL_MAX,
  HERO_STAR_MIN, HERO_STAR_MAX,
  getSkillEffectiveStar, setSkillStarOverride,
  getWeaponEffectiveLevel, setWeaponLevelOverride,
  resetHeroOverride, heroHasCustom,
} from "./state.js";
import { getAllHeroesAndSkills, formatSkillDescription, formatWeaponDescription, getSkillById, getWeaponByHeroId } from "./core.js";

let openHeroId = null;

function escapeHtml(str) {
  const div = document.createElement("div");
  div.textContent = str;
  return div.innerHTML;
}

function renderIconWithStars(iconUrl, name, layers, size = "") {
  const sizeClass = size === "sm" ? "sm" : "";
  const img = iconUrl
    ? `<img src="${iconUrl}" alt="${escapeHtml(name)}">`
    : `<div class="icon-placeholder-text">${escapeHtml(name).slice(0, 4)}</div>`;

  return `<div class="icon-layered ${sizeClass}">${img}</div>`;
}

/** 更新 <input type=range> 的填色比例（--pct），讓現代化滑桿樣式生效 */
function updateRangeFill(input) {
  const min = Number(input.min), max = Number(input.max), val = Number(input.value);
  const pct = max > min ? ((val - min) / (max - min)) * 100 : 0;
  input.style.setProperty("--pct", pct + "%");
}

/**
 * 星星按鈕元件（用於「英雄星級」）：以實心 / 空心金色星星表示目前等級，
 * 點擊第 i 顆星即設為 i 級；再次點擊目前等級的最後一顆星則退回 i-1 級，
 * 讓使用者也能回到 0 級（顯示為 00000）。
 */
function renderStarRating({ value, max, onChange }) {
  const wrap = document.createElement("div");
  wrap.className = "star-rating";
  let star = "";
  for (let i = 0; i < max; i++) {
    if (i < value) {
      star += "★";
    }
    else {
      star += "☆";
    }
  }
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "star-rating-button"
  btn.textContent = star;
  btn.addEventListener("click", () => {
    onChange(value);
  });

  if (AppState.globalStars.charStar == value) {
    btn.classList.add("is-selected")
  }
  wrap.appendChild(btn);
  return wrap;
}

/** 滑桿元件（用於技能等級全域預設值） */
function makeMiniSlider({ labelText, swatchClass, value, min, max, onChange }) {
  const wrap = document.createElement("div");
  wrap.className = "mini-slider-item";
  wrap.innerHTML = `
    <div class="label-row">
      <span class="name"><span class="swatch ${swatchClass}"></span>${labelText}</span>
      <span class="value">${value}</span>
    </div>
    <input type="range" class="mini" min="${min}" max="${max}" step="1" value="${value}">
  `;
  const input = wrap.querySelector("input");
  const valueEl = wrap.querySelector(".value");
  updateRangeFill(input);
  input.addEventListener("input", () => {
    valueEl.textContent = input.value;
    updateRangeFill(input);
    onChange(Number(input.value));
  });
  return wrap;
}

/** +/- 一級一級調整的 stepper 元件（用於技能星級 / 專武等級） */
function makeStepper({ value, min, max, onChange, size = "" }) {
  const wrap = document.createElement("div");
  wrap.className = "stepper" + (size === "sm" ? " sm" : "");

  const minusBtn = document.createElement("button");
  minusBtn.type = "button";
  minusBtn.textContent = "－";
  const valueEl = document.createElement("span");
  valueEl.className = "value";
  valueEl.textContent = value;
  const plusBtn = document.createElement("button");
  plusBtn.type = "button";
  plusBtn.textContent = "＋";

  const fixNum = max === 6 ? 1 : 0;
  const star = max === 6 ? "★" : "";
  function refresh(v) {
    valueEl.textContent = (v - fixNum) + star;
    minusBtn.disabled = v <= min;
    plusBtn.disabled = v >= max;
  }
  refresh(value);

  let showValue = valueEl.textContent;
  if (max === 6) {
    showValue = showValue.substring(0, showValue.length - 1)
  }
  minusBtn.addEventListener("click", () => {
    const next = Math.max(min, Number(showValue) - 1 + fixNum);
    refresh(next);
    onChange(next);
  });
  plusBtn.addEventListener("click", () => {
    const next = Math.min(max, Number(showValue) + 1 + fixNum);
    refresh(next);
    onChange(next);
  });

  wrap.appendChild(minusBtn);
  wrap.appendChild(valueEl);
  wrap.appendChild(plusBtn);
  return wrap;
}

export function render() {
  const searchInput = document.getElementById("searchInput");
  const query = searchInput.value.trim().toLowerCase();
  const heroList = document.getElementById("heroList");
  const emptyState = document.getElementById("emptyState");

  const showChinaData = document.getElementById("mainlandDataToggle");
  AppState.isOverSea = showChinaData.checked;

  const heroes = getAllHeroesAndSkills();
  const skillMap = new Map(heroes.flatMap(hero => hero.skillIds.map(id => [id, getSkillById(id)])));

  const filtered = heroes.filter(hero => {
    if (!query) return true;
    if (hero.name.toLowerCase().includes(query)) return true;

    return hero.skillIds.some(id => {
      const s = getSkillById(id);
      const name = AppState.strings[s.Name] || "";
      return name.toLowerCase().includes(query);
    });
  });

  heroList.innerHTML = "";
  emptyState.style.display = filtered.length === 0 ? "block" : "none";

  filtered.forEach(hero => {
    const isOpen = hero.heroId === openHeroId;
    const heroCharStar = AppState.globalStars.charStar; // 英雄星級全域共用，不再逐一覆寫

    const card = document.createElement("div");
    card.className = "hero-card" + (isOpen ? " open" : "");

    const heroIconHtml = renderIconWithStars(hero.iconUrl, hero.name, [
      { type: "char", value: heroCharStar },
    ]);

    const head = document.createElement("div");
    head.className = "hero-head";
    head.innerHTML = `
      <span class="expand-arrow">▶</span>
      ${heroIconHtml}
      <span class="hero-name">${escapeHtml(hero.name)}</span>
      <span class="hero-id">#${hero.heroId}</span>
    `;

    const spacer = document.createElement("span");
    spacer.className = "hero-head-spacer";
    head.appendChild(spacer);

    // 先隱藏後續再處理
    // if (heroHasCustom(hero.heroId)) {
    //   const tag = document.createElement("span");
    //   tag.className = "custom-tag";
    //   tag.textContent = "已自訂";
    //   head.appendChild(tag);
    // }
    head.addEventListener("click", (e) => {
      if (e.target.closest(".reset-btn")) return;
      openHeroId = isOpen ? null : hero.heroId;
      render();
    });
    card.appendChild(head);

    const body = document.createElement("div");
    body.className = "hero-body";

    const skillsTitle = document.createElement("div");
    skillsTitle.className = "section-title";
    skillsTitle.textContent = "技能／專武";
    body.appendChild(skillsTitle);

    // ---- 每個技能：icon 下方顯示目前星級 + stepper 獨立調整 ----
    hero.skillIds.forEach(skillId => {
      const skill = skillMap.get(skillId);
      if (!skill) return;

      let skillStar = getSkillEffectiveStar(hero.heroId, skillId);
      const maxLevel = skill.LevelMax !== undefined ? skill.LevelMax : 10;
      if (skillStar > maxLevel) skillStar = maxLevel;

      let skillIcon = skill.SkillIcon
      if (maxLevel == 6) skillIcon = Number(hero.heroId)+50000;

      const skillIconUrl = "assets\\skill\\" + skillIcon + ".png";  // 技能圖示路徑
      const skillIconHtml = renderIconWithStars(skillIconUrl, skill.name, [], "sm");
      const effective = { charStar: heroCharStar, skillStar: skillStar };
      const descHtml = formatSkillDescription(skillId, effective);

      const row = document.createElement("div");
      row.className = "skill-row";

      const iconCol = document.createElement("div");
      iconCol.className = "skill-icon-col";
      iconCol.innerHTML = skillIconHtml;
      iconCol.appendChild(makeStepper({
        value: skillStar, min: SKILL_STAR_MIN, max: maxLevel, size: "sm",
        onChange: (v) => { setSkillStarOverride(hero.heroId, skillId, v); render(); },
      }));

      const skillName = AppState.strings[skill.SkillName] || skill.name;
      const textCol = document.createElement("div");
      textCol.className = "skill-text";
      textCol.innerHTML = `
        <div class="skill-name-row">
          <span class="skill-name">${escapeHtml(skillName)}</span>
          <span class="skill-id">#${skillId}</span>
        </div>
        <div class="skill-desc">${descHtml}</div>
      `;

      row.appendChild(iconCol);
      row.appendChild(textCol);
      body.appendChild(row);
    });

    // ---- 專武：併入技能清單，用同一套 icon + stepper 呈現 ----
    if (hero.weaponId) {
      const weapon_info = getWeaponByHeroId(hero.heroId);
      const weapon = getSkillById(hero.weaponId);
      if (weapon) {
        let weaponLevel = getSkillEffectiveStar(hero.heroId, hero.weaponId);  // 專武等級（每個角色各自記錄自己的專武等級）
        if (weaponLevel > weapon.LevelMax) weaponLevel = weapon.LevelMax; // clamp to max 5
        const weaponIconUrl = "assets\\skill\\" + weapon.SkillIcon + ".png";  // 專武圖示路徑
        const weaponIconHtml = renderIconWithStars(weaponIconUrl, weapon.name, [], "sm");
        const effective = { charStar: heroCharStar, skillStar: weaponLevel };
        const descHtml = formatSkillDescription(hero.weaponId, effective);

        const row = document.createElement("div");
        row.className = "skill-row";

        const iconCol = document.createElement("div");
        iconCol.className = "skill-icon-col";
        iconCol.innerHTML = weaponIconHtml;
        iconCol.appendChild(makeStepper({
          value: weaponLevel, min: WEAPON_LEVEL_MIN, max: weapon.LevelMax, size: "sm",
          onChange: (v) => { setSkillStarOverride(hero.heroId, hero.weaponId, v); render(); },
        }));

        const weaponName = AppState.strings[weapon_info.Name] || weapon.name;
        const textCol = document.createElement("div");
        textCol.className = "skill-text";
        textCol.innerHTML = `
          <div class="skill-name-row">
            <span class="weapon-tag">專武</span>
            <span class="skill-name">${escapeHtml(weaponName)}</span>
            <span class="skill-id">#${hero.weaponId}</span>
          </div>
          <div class="skill-desc">${descHtml}</div>
        `;

        row.appendChild(iconCol);
        row.appendChild(textCol);
        body.appendChild(row);
      }
    }

    card.appendChild(body);
    heroList.appendChild(card);
  });
}

/** 頂部「英雄星級」星星按鈕：全域唯一設定入口 */
export function renderGlobalCharStarStars() {
  const container = document.getElementById("g_charStar_stars");
  container.innerHTML = "";

  for (let i = 0; i <= HERO_STAR_MAX; i++) {
    container.appendChild(renderStarRating({
      value: i,
      max: HERO_STAR_MAX,
      onChange: (v) => {
        AppState.globalStars.charStar = v;
        renderGlobalCharStarStars();
        render();
      },
    }));
  }
}

export { updateRangeFill };
