/* =========================================================================
 * state.js —— 資料載入 + 全域狀態
 * -------------------------------------------------------------------------
 * 角色星級：只有頂部「全域預設值」一個設定入口（星星按鈕），
 *           所有角色共用同一個值，不再支援逐一覆寫。
 * 技能星級：頂部「技能等級」滑桿是預設值，每個技能可用 +/- 各自覆寫。
 * 專武等級：不再有獨立的全域滑桿，併入技能清單中以 +/- 個別調整，
 *           每個角色各自記錄自己的專武等級（預設值見 WEAPON_LEVEL_DEFAULT）。
 * ========================================================================= */

export const SKILL_STAR_MIN = 1;
export const SKILL_STAR_MAX = 10;

export const WEAPON_LEVEL_MIN = 1;
export const WEAPON_LEVEL_MAX = 6;
export const WEAPON_LEVEL_DEFAULT = 0;

export const HERO_STAR_MIN = 0;
export const HERO_STAR_MAX = 5;

export const AppState = {
  heroes: [],   // 從 data/heroes.json 載入
  skills: [],   // 從 data/skills.json 載入
  weapons: [],  // 從 data/weapons.json 載入
  strings: {},   // 從 data/strings.json 載入（暫時沒用到）

  // 全域預設值
  globalStars: {
    charStar: 5,     // 英雄星級（唯一設定入口，所有角色共用）
    skillLevel: 10,   // 每個技能「技能星級」的預設值
  },

  isOverSea: false,

  // 個別覆寫：heroOverrides[heroId] = { weaponLevel?, skills: { [skillId]: { skillStar? } } }
  heroOverrides: {},
};

/** 從 /data 底下的三份 JSON 載入資料，填入 AppState */
export async function loadData() {
  const [heroesRes, skillsRes, weaponsRes, stringsRes] = await Promise.all([
    fetch("data/heroes.json"),
    fetch("data/skills.json"),
    fetch("data/weapons.json"),
    fetch("data/strings.tsv"),
  ]);

  if (!heroesRes.ok || !skillsRes.ok || !weaponsRes.ok || !stringsRes.ok) {
    throw new Error("資料載入失敗，請確認 data/ 底下的 JSON 檔案存在且伺服器正常運作");
  }

  AppState.heroes = await heroesRes.json();
  AppState.skills = await skillsRes.json();
  AppState.weapons = await weaponsRes.json();

  const stringMap = {};
  const tsvText = await stringsRes.text();
  const lines = tsvText.split("\n").filter(line => line.trim());
  for (const line of lines) {
    const [id, text] = line.split("\t");
    stringMap[id] = text;
  }
  AppState.strings = stringMap;
}

function getHeroOverride(heroId) {
  if (!AppState.heroOverrides[heroId]) AppState.heroOverrides[heroId] = { skills: {} };
  return AppState.heroOverrides[heroId];
}

export function heroHasCustom(heroId) {
  const ov = AppState.heroOverrides[heroId];
  if (!ov) return false;
  if (ov.weaponLevel !== undefined) return true;
  return Object.values(ov.skills || {}).some(s => s.skillStar !== undefined);
}

/** 取得某技能「技能星級」目前生效值：有覆寫用覆寫，否則用全域的 skillLevel 當預設 */
export function getSkillEffectiveStar(heroId, skillId) {
  const ov = AppState.heroOverrides[heroId];
  const skillOv = ov && ov.skills && ov.skills[skillId];
  if (skillOv && skillOv.skillStar !== undefined) return skillOv.skillStar;
  return AppState.globalStars.skillLevel;
}

export function setSkillStarOverride(heroId, skillId, value) {
  const ov = getHeroOverride(heroId);
  if (!ov.skills[skillId]) ov.skills[skillId] = {};
  ov.skills[skillId].skillStar = value;
}

/** 取得某角色的專武等級：有覆寫用覆寫，否則用預設值 */
export function getWeaponEffectiveLevel(heroId) {
  const ov = AppState.heroOverrides[heroId];
  if (ov && ov.weaponLevel !== undefined) return ov.weaponLevel;
  return WEAPON_LEVEL_DEFAULT;
}

export function setWeaponLevelOverride(heroId, value) {
  getHeroOverride(heroId).weaponLevel = value;
}

export function resetHeroOverride(heroId) {
  AppState.heroOverrides[heroId] = { skills: {} };
}
